package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class ReelMotionTest{
 @Test public void distanceAcceleratesThenHasConstantCruiseSpeed(){assertEquals(0,SlotsView.reelDistance(0),.001);assertTrue(SlotsView.reelDistance(100)-SlotsView.reelDistance(50)>SlotsView.reelDistance(50));assertEquals(SlotsView.reelDistance(400)-SlotsView.reelDistance(300),SlotsView.reelDistance(600)-SlotsView.reelDistance(500),.01);assertTrue(SlotsView.reelDistance(221)>SlotsView.reelDistance(220));}
 @GraphicsMode(GraphicsMode.Mode.NATIVE) @Test public void movingStripPreview()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.layout(0,0,640,1040);v.onTouchEvent(android.view.MotionEvent.obtain(0,0,android.view.MotionEvent.ACTION_DOWN,450,v.controlsTop()+20,0));android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(640,1040,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-reelmotion.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}}
}
